export const MEMBER_DEFAULTS=[{id:"maya",name:"Maya Lin",role:"Staff Systems Engineer",location:"Zürich · CET (UTC+1)",statusNote:"Available for architecture review"},{id:"jonas",name:"Jonas Berg",role:"Principal Product Designer",location:"Stockholm · CET (UTC+1)",statusNote:"In design critique until 16:00"},{id:"priya",name:"Priya Nair",role:"Runtime Lead",location:"Bengaluru · IST (UTC+5:30)",statusNote:"Pairing on SharedWorker scheduling"}];export function initialsOf(e=""){return String(e||"").trim().split(/\s+/).filter(Boolean).slice(0,2).map(e=>e[0].toUpperCase()).join("")||"?"}export function seedMembers(){return MEMBER_DEFAULTS.map(e=>({...e}))}export function resetMemberRecord(e){if(!e?.isRecord)return!1;const t=MEMBER_DEFAULTS.find(t=>t.id===e.id);return!!t&&(e.set({location:t.location,name:t.name,role:t.role,statusNote:t.statusNote}),!0)}